// Description:
// Reshuflle filter sitting between shuffle stage and global load store unit.
// Intercepts loads and stores generated by reshuffles and services them
// with the buffer while not transmitting the request to the glsu.

module reshuffle_filter
  import ara_pkg::*;
  import rvv_pkg::*;
#(
    parameter  int unsigned NrLanes             = 0,
    parameter  int unsigned NrClusters          = 0,
    parameter  int unsigned ClusterAxiDataWidth = 0,
    parameter  type         cluster_axi_req_t   = logic,
    parameter  type         cluster_axi_resp_t  = logic,
    parameter  type         axi_req_t           = logic,
    parameter  type         axi_resp_t          = logic,
    localparam int unsigned DEPTH               = (NrLanes * 1024) / ClusterAxiDataWidth
) (
    input logic clk_i,
    input logic rst_ni,

    input cluster_metadata_t [NrClusters-1:0] aw_metadata_i,
    input cluster_metadata_t [NrClusters-1:0] ar_metadata_i,

    // To ARA
    input  cluster_axi_req_t  [NrClusters-1:0] axi_req_i,
    output cluster_axi_resp_t [NrClusters-1:0] axi_resp_o,

    // To GLSU
    input  cluster_axi_resp_t [NrClusters-1:0] axi_resp_i,
    output cluster_axi_req_t  [NrClusters-1:0] axi_req_o
);

  // Reshuffle buffer
  logic [ClusterAxiDataWidth-1:0] rs_buffer[DEPTH][NrClusters-1:0];

  logic [NrClusters-1:0] rs_w_clusters_valid;

  // Transaction counters
  logic [$clog2(DEPTH):0] rs_w_count_q, rs_w_count_d;
  logic [$clog2(DEPTH):0] rs_r_count_q, rs_r_count_d;

  logic rs_ar_valid_toggle_d, rs_ar_valid_toggle_q;

  // Response to ARA
  cluster_axi_resp_t [NrClusters-1:0] axi_resp_d;
  // Request to GLSU
  cluster_axi_req_t  [NrClusters-1:0] axi_req_d;

  logic b_pending_d, b_pending_q;
  logic [$bits(axi_req_i[0].aw.id)-1:0] aw_id_d, aw_id_q;
  logic ar_all_valid, r_all_ready, b_all_ready;
  logic [$bits(axi_req_i[0].ar.id)-1:0] ar_id_q[NrClusters], ar_id_d[NrClusters];

  logic rs_store_en, rs_store, rs_load;

  assign axi_resp_o = axi_resp_d;
  assign axi_req_o = axi_req_d;
  assign rs_store = aw_metadata_i[0].is_reshuffle && (aw_metadata_i[0].op == VSE);
  assign rs_load = ar_metadata_i[0].is_reshuffle && (ar_metadata_i[0].op == VLE);
  assign rs_store_en = rs_store && (&rs_w_clusters_valid);


  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (~rst_ni) begin
      rs_w_count_q         <= '0;
      rs_r_count_q         <= '0;
      rs_ar_valid_toggle_q <= '0;
      b_pending_q          <= 1'b0;
      aw_id_q              <= '0;
      for (int j = 0; j < NrClusters; j++) begin
        ar_id_q[j] <= '0;
      end
    end else begin
      rs_w_count_q         <= rs_w_count_d;
      rs_r_count_q         <= rs_r_count_d;
      rs_ar_valid_toggle_q <= rs_ar_valid_toggle_d;
      b_pending_q          <= b_pending_d;
      aw_id_q              <= aw_id_d;
      ar_id_q              <= ar_id_d;
    end
  end

  always_ff @(posedge clk_i) begin
    if (rs_store_en) begin
      for (int j = 0; j < NrClusters; j++) begin
        rs_buffer[rs_w_count_q][j] <= axi_req_i[j].w.data;
      end
    end
  end

  always_comb begin

    // default assignments
    axi_resp_d           = axi_resp_i;
    axi_req_d            = axi_req_i;
    rs_w_count_d         = rs_w_count_q;
    rs_r_count_d         = rs_r_count_q;
    rs_ar_valid_toggle_d = rs_ar_valid_toggle_q;
    b_pending_d          = b_pending_q;
    aw_id_d              = aw_id_q;
    ar_id_d              = ar_id_q;

    for (int j = 0; j < NrClusters; j++) begin
      rs_w_clusters_valid[j] = axi_req_i[j].w_valid;
    end

    // Handshake summaries
    // The shuffle stage synchronizes unit-stride loads across clusters and
    // forwards only cluster 0's AR request.
    ar_all_valid = axi_req_i[0].ar_valid;
    r_all_ready  = 1'b1;
    b_all_ready  = 1'b1;

    for (int j = 0; j < NrClusters; j++) begin
      r_all_ready &= axi_req_i[j].r_ready;
      b_all_ready &= axi_req_i[j].b_ready;
    end

    if (rs_store) begin
      if (axi_req_i[0].aw_valid) begin
        aw_id_d = axi_req_i[0].aw.id;
      end
    end


    if (rs_store || rs_load) begin

      for (int j = 0; j < NrClusters; j++) begin
        if (rs_store) begin
          axi_req_d[j].aw_valid = 1'b0;   // no reshuffle writes reach GLSU
          axi_req_d[j].w_valid  = 1'b0;
          // B channel held until every cluster accepts it
          axi_resp_d[j].b_valid = b_pending_q;
          axi_resp_d[j].b.id    = aw_id_q;
          axi_resp_d[j].b.resp  = 2'b00;
          axi_resp_d[j].b.user  = '0;
        end
        if (rs_load) axi_req_d[j].ar_valid = 1'b0;
      end

      if (rs_store && b_pending_q && b_all_ready) begin
        b_pending_d = 1'b0;
      end


      ////////////////////////
      //  RESHUFFLE STORES  //
      ////////////////////////

      if (rs_store) begin
        // Fill Reshuffle Buffer and generate response

        if (&rs_w_clusters_valid) begin

          for (int j = 0; j < NrClusters; j++) begin
            axi_resp_d[j].aw_ready = 1'b1;
            axi_resp_d[j].w_ready  = 1'b1;
          end

          if (rs_w_count_q == (DEPTH - 1)) begin
            rs_w_count_d = '0;
            for (int j = 0; j < NrClusters; j++) begin
              axi_resp_d[j].b_valid = 1'b1;
            end
            // Only arm the hold if ARA can't accept B right now
            if (!b_all_ready) begin
              b_pending_d = 1'b1;
            end
          end else begin
            for (int j = 0; j < NrClusters; j++) begin
              axi_resp_d[j].b_valid = '0;
            end
            rs_w_count_d = rs_w_count_q + 1;
          end
        end

      end

      ///////////////////////
      //  RESHUFFLE LOADS  //
      ///////////////////////

      if (rs_load) begin

        if (!rs_ar_valid_toggle_q) begin
          // Accept the synchronized group request from cluster 0.
          for (int j = 0; j < NrClusters; j++) begin
            axi_resp_d[j].ar_ready = 1'b1;
            axi_resp_d[j].r_valid  = 1'b0;
          end
          if (ar_all_valid) begin
            rs_ar_valid_toggle_d = 1'b1;
            rs_r_count_d         = '0;

            for (int j = 0; j < NrClusters; j++) begin
              ar_id_d[j] = axi_req_i[0].ar.id;
            end

          end
        end else begin
          for (int j = 0; j < NrClusters; j++) begin
            axi_resp_d[j].r_valid  = 1'b1;
            axi_resp_d[j].r.data   = rs_buffer[rs_r_count_q][j];
            axi_resp_d[j].r.id     = ar_id_q[j];
            axi_resp_d[j].r.resp   = 2'b00;
            axi_resp_d[j].r.user   = '0;
            axi_resp_d[j].ar_ready = 1'b1;
            axi_resp_d[j].r.last   = (rs_r_count_q == DEPTH - 1);
          end

          if (r_all_ready) begin
            if (rs_r_count_q == DEPTH - 1) begin
              rs_r_count_d         = '0;
              rs_ar_valid_toggle_d = 1'b0;
            end else begin
              rs_r_count_d = rs_r_count_q + 1;
            end
          end
        end
      end
    end

  end

endmodule
